#!/usr/bin/env python3
# AI DISCLAIMER: All of the text in this file was generated by AI.
"""G020: check txs_prunable_tip in a stopped node's database (read-only, through mdb_dump and mdb_stat built from the
tree's own liblmdb).

Checks: (1) along the table's key order (tx id), the block heights never fall; (2) no entry has left the tip, that is
block_height + 5500 < the database's height - MARGIN (MARGIN = 100 blocks: the last pass ran after the last batch).
Prints the entry count, the first and last (tx id, height), the number of falls, the number of expired entries, and
"TIPCHECK ok" or "TIPCHECK FAIL".
usage: python3 tipcheck.py <dir holding mdb_dump and mdb_stat> <lmdb dir>
"""
import struct, subprocess, sys

tools, db = sys.argv[1], sys.argv[2]
TIP, MARGIN = 5500, 100
st = subprocess.run([tools + "/mdb_stat", "-s", "blocks", db], capture_output=True, text=True, check=True).stdout
height = int([l for l in st.splitlines() if "Entries:" in l][0].split()[-1])
out = subprocess.run([tools + "/mdb_dump", "-s", "txs_prunable_tip", db], capture_output=True, text=True, check=True).stdout
lines = out.splitlines()
data = lines[lines.index("HEADER=END") + 1:]
data = [l.strip() for l in data if l.startswith(" ")]
assert len(data) % 2 == 0, "odd number of key/value lines"
entries = []
for i in range(0, len(data), 2):
    k, v = bytes.fromhex(data[i]), bytes.fromhex(data[i + 1])
    assert len(k) == 8 and len(v) == 8, (len(k), len(v))
    entries.append((struct.unpack("<Q", k)[0], struct.unpack("<Q", v)[0]))
falls = sum(1 for a, b in zip(entries, entries[1:]) if b[1] < a[1])
ids_sorted = all(b[0] > a[0] for a, b in zip(entries, entries[1:]))
expired = sum(1 for _, h in entries if h + TIP < height - MARGIN)
print("db height %d; tip entries %d; first %s; last %s" % (height, len(entries), entries[0] if entries else None, entries[-1] if entries else None))
print("tx ids strictly increasing: %s; height falls along the key order: %d; entries out of the tip by more than %d blocks: %d" % (ids_sorted, falls, MARGIN, expired))
print("TIPCHECK %s" % ("ok" if ids_sorted and falls == 0 and expired == 0 else "FAIL"))
